using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;

namespace WolvenKit.App.Services.Themes;

/// <summary>
/// One overridable color resource. Generated by tools/themes/generate_theme_schema.py.
/// </summary>
public sealed class ThemeSchemaEntry
{
    public string Key { get; set; } = "";

    public string Group { get; set; } = "";

    public string DisplayName { get; set; } = "";

    /// <summary>
    /// "Color" or "Brush" — the type of the resource in App.Styles.xaml.
    /// The actual type is re-checked at runtime.
    /// </summary>
    public string Kind { get; set; } = "Color";

    /// <summary>
    /// SolidColorBrush resources defined as <c>Color="{StaticResource Key}"</c>.
    /// They must be regenerated when <see cref="Key"/> is overridden.
    /// </summary>
    public List<string>? DerivedBrushes { get; set; }
}

public sealed class ThemeSchema
{
    private const string EmbeddedResourceName = "WolvenKit.App.Resources.Themes.theme-schema.json";

    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNameCaseInsensitive = true
    };

    public List<ThemeSchemaEntry> Entries { get; set; } = [];

    private Dictionary<string, ThemeSchemaEntry>? _byKey;

    /// <summary>Adds a key discovered at runtime (e.g. Syncfusion theme brushes).</summary>
    public void AddEntry(ThemeSchemaEntry entry)
    {
        if (Find(entry.Key) is not null)
        {
            return;
        }
        Entries.Add(entry);
        _byKey![entry.Key] = entry;
    }

    public ThemeSchemaEntry? Find(string key)
    {
        _byKey ??= Entries.ToDictionary(e => e.Key, StringComparer.Ordinal);
        return _byKey.GetValueOrDefault(key);
    }

    public static ThemeSchema LoadEmbedded()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(EmbeddedResourceName)
                           ?? throw new FileNotFoundException($"Embedded resource {EmbeddedResourceName} not found");
        return JsonSerializer.Deserialize<ThemeSchema>(stream, s_options) ?? new ThemeSchema();
    }
}
